#!/usr/bin/env bash
# ============================================================================
# VideoMind, Part 15b1: home, library, courses, upload and search in five languages
# ============================================================================
# FOR THE rebuild BRANCH. It refuses to run on main: apply it on rebuild,
# check it, then fast forward main.
#
# After this part (plan: claude/language-plan.md):
#   * Home (signed in and the visitor page with its example lecture), the
#     library and its category pages, Courses and each course, the video
#     cards, Upload with the details form, and Search are translated
#   * lengths, sizes and "5 minutes ago" come from the browser's Intl data
#     in each language (src/lib/format.ts); category and visibility names
#     are translated (useLabels in src/lib/categories.ts)
#   * titles, transcript lines, chapter names and descriptions keep their
#     own text direction (dir="auto"), so a Spanish line in the Arabic
#     interface still reads left to right
#   * Search marks matching words in any script, Arabic included
#   * the frontend lockfile gets back one entry that npm install dropped
#     after 15a; without it npm ci refuses the lockfile
#   * still off by default: production is unchanged while
#     NEXT_PUBLIC_LANGUAGES is not on
#
#   FRONTEND   1 new file, 17 changed. No migration, no new package
#
#   ./vm_lang_b1.sh            apply (needs Part 14f on the branch)
#   ./vm_lang_b1.sh --force    apply even if local files differ from GitHub
#   ./vm_lang_b1.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_lang"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_lang_b1_backups"

ADD=(
  "frontend/src/lib/format.ts"
)
MOD=(
  "frontend/src/lib/categories.ts"
  "frontend/src/messages/en.json"
  "frontend/src/messages/es.json"
  "frontend/src/messages/fr.json"
  "frontend/src/messages/ar.json"
  "frontend/src/messages/pt.json"
  "frontend/src/app/page.tsx"
  "frontend/src/app/upload/page.tsx"
  "frontend/src/app/search/page.tsx"
  "frontend/src/app/library/courses/page.tsx"
  "frontend/src/components/library/LibraryView.tsx"
  "frontend/src/components/library/CourseView.tsx"
  "frontend/src/components/video/VideoCard.tsx"
  "frontend/src/components/video/VideoInfoForm.tsx"
  "frontend/src/components/upload/UploadZone.tsx"
  "frontend/src/components/search/SearchInterface.tsx"
  "frontend/package-lock.json"
)
