verify "$TMPD/a0" "${NEW_ADD[0]}" "frontend/src/lib/format.ts"

grep -q 'vm_lang' "$TMPD/a0" || die "format.ts payload missing marker. Aborting."
grep -q 'export function useFormat' "$TMPD/a0" || die "format.ts payload is wrong. Aborting."
grep -q -- 'export function useLabels' "$TMPD/m0" || die "categories.ts payload is wrong. Aborting."
grep -q -- '"uploadPage"' "$TMPD/m1" || die "en.json payload is wrong. Aborting."
grep -q -- '"languageTitle"' "$TMPD/m1" || die "en.json payload lost 15a. Aborting."
grep -q -- 'متابعة المشاهدة' "$TMPD/m4" || die "frontend/src/messages/ar.json payload is wrong. Aborting."
grep -q -- 'useTranslations("home")' "$TMPD/m6" || die "page.tsx payload is wrong. Aborting."
grep -q -- 'useTranslations("library")' "$TMPD/m10" || die "LibraryView.tsx payload is wrong. Aborting."
grep -q -- 'stepKey' "$TMPD/m12" || die "VideoCard.tsx payload is wrong. Aborting."
grep -q -- 'useTranslations("upload")' "$TMPD/m14" || die "UploadZone.tsx payload is wrong. Aborting."
grep -q -- 'useUploadBlobs' "$TMPD/m14" || die "UploadZone.tsx payload lost the Shelby step. Aborting."
grep -q -- 'p{L}' "$TMPD/m15" || die "SearchInterface.tsx payload is wrong. Aborting."
grep -q -- 'node_modules/next-intl/node_modules/@swc/helpers' "$TMPD/m16" || die "package-lock.json payload is wrong. Aborting."
say "18 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied Part 15b1 (home, library, courses, upload, search)."
say "No migration. The lockfile changed, so run npm ci (or npm install) in frontend."
say "Install the new package and verify before pushing:"
say "  (cd frontend && npm ci && npx tsc --noEmit && npm run build)"
say "To see the languages on the preview only: Vercel, the project, Settings,"
say "Environment Variables, NEXT_PUBLIC_LANGUAGES = on, environment Preview only."
say "Leave it unset for Production until Part 15c."
say "Then commit and push rebuild, check the preview, and fast forward main:"
say "  git checkout main && git pull origin main && git merge --ff-only origin/rebuild && git push origin main && git checkout rebuild"
say "Undo: ./vm_lang_b1.sh --revert"
